#[test]
fn sqlite_snapshot_vcs_independent_complete_semantic_cells_precede_native_ownership(){
 use std::{io::Write,process::{Command,Stdio}};
 let limits=SqliteDatabaseLimits::default();
 for word in laws()["signed64"].as_array().unwrap(){let mut snapshot=fixture();snapshot.counter=word.as_str().unwrap().parse().unwrap();let expected=database(&snapshot);let bytes=file(&snapshot);
  let script=r#"import{Database}from'bun:sqlite';const db=Database.deserialize(new Uint8Array(await Bun.stdin.arrayBuffer()),{safeIntegers:true});let cells=0n,rows=0n;const widths={vcs_document:6,vcs_tag:4};for(const table of db.query("SELECT name FROM sqlite_schema WHERE type='table' ORDER BY name").all()){const name='"'+table.name.replaceAll('"','""')+'"',columns=db.query("PRAGMA table_info("+name+")").all();if(columns.length!==widths[table.name])throw Error('width');rows+=db.query("SELECT COUNT(*) count FROM "+name).get().count;for(const column of columns){const key='"'+column.name.replaceAll('"','""')+'"';cells+=db.query("SELECT COALESCE(SUM(CASE typeof("+key+") WHEN 'integer' THEN 8 WHEN 'real' THEN 8 WHEN 'text' THEN length(CAST("+key+" AS BLOB)) WHEN 'blob' THEN length("+key+") ELSE 0 END),0) bytes FROM "+name).get().bytes;}}await Bun.write(Bun.stdout,String(rows)+' '+String(cells));db.close();"#;
  let mut child=Command::new("bun").args(["-e",script]).stdin(Stdio::piped()).stdout(Stdio::piped()).stderr(Stdio::piped()).spawn().unwrap();child.stdin.take().unwrap().write_all(&bytes).unwrap();let output=child.wait_with_output().unwrap();assert!(output.status.success(),"{}",String::from_utf8_lossy(&output.stderr));let output=String::from_utf8(output.stdout).unwrap();let mut parts=output.split_whitespace();let rows=parts.next().unwrap().parse::<usize>().unwrap();let cells=parts.next().unwrap().parse::<usize>().unwrap();assert!(parts.next().is_none());assert_eq!(rows,laws()["semanticCells"]["fullRows"].as_u64().unwrap()as usize);assert!(cells>0);
  let exact=SqliteDatabaseLimits{max_rows:rows,max_value_bytes:cells,..limits};assert_eq!(snapshot.to_sqlite_database(&mut SqliteSnapshotControl::new(&mut |_|true,exact)).unwrap(),expected);
  for encoding in[SnapshotEncoding::Binary,SnapshotEncoding::Text]{snapshot.preflight_sqlite_snapshot_encoding(encoding,&mut SqliteSnapshotControl::new(&mut |_|true,exact)).unwrap();let payload=snapshot.encode_sqlite_snapshot_native(encoding,&mut SqliteSnapshotControl::new(&mut |_|true,exact)).unwrap();assert_eq!(VcsSnapshot::decode_sqlite_snapshot_native(&payload,&mut SqliteSnapshotControl::new(&mut |_|true,exact)).unwrap(),snapshot);
   for restricted in[SqliteDatabaseLimits{max_rows:rows-1,..exact},SqliteDatabaseLimits{max_value_bytes:cells-1,..exact}]{assert!(snapshot.to_sqlite_database(&mut SqliteSnapshotControl::new(&mut |_|true,restricted)).is_err());assert!(snapshot.preflight_sqlite_snapshot_encoding(encoding,&mut SqliteSnapshotControl::new(&mut |_|true,restricted)).is_err());assert!(snapshot.encode_sqlite_snapshot_native(encoding,&mut SqliteSnapshotControl::new(&mut |_|true,restricted)).is_err());assert!(VcsSnapshot::decode_sqlite_snapshot_native(&payload,&mut SqliteSnapshotControl::new(&mut |_|true,restricted)).is_err());}
  }
 }eprintln!("[DEBUG] VCS complete authored cells match independent SQLite before typed owner binding");
}

